"""
Application configuration settings.
"""
from typing import Optional
from pydantic_settings import BaseSettings
from functools import lru_cache
import os
from pydantic import ValidationError


class Settings(BaseSettings):
    """Application settings."""

    # Application
    APP_NAME: str = "My Application"
    APP_VERSION: str = "1.0.0"
    DEBUG: bool = False

    # Database
    DATABASE_URL: str = "sqlite:///./app.db"

    # Security
    SECRET_KEY: str = "your-secret-key-here"
    ALGORITHM: str = "HS256"
    ACCESS_TOKEN_EXPIRE_MINUTES: int = 30

    # CORS
    BACKEND_CORS_ORIGINS: list = []

    # API
    API_V1_PREFIX: str = "/api/v1"

    class Config:
        env_file = ".env"
        case_sensitive = True


@lru_cache()
def get_settings() -> Settings:
    """Get cached settings instance with exception handling."""
    try:
        # 尝试正常加载配置
        return Settings()
    except ValidationError as e:
        # 配置文件格式错误（验证失败）
        # 检查 .env 文件是否存在
        if os.path.exists(".env"):
            # 文件存在但格式错误，使用默认配置
            return Settings(_env_file=None)
        else:
            # 文件不存在使用默认配置
            return Settings(_env_file=None)
    except FileNotFoundError:
        # 配置文件不存在使用默认配置
        return Settings(_env_file=None)
    except Exception:
        # 其他异常使用默认配置
        return Settings(_env_file=None)


settings = get_settings()

import os
from typing import Any, Optional


class Settings:
    """应用配置类"""

    def __init__(self):
        self._config: dict = {}
        self._load_config()

    def _load_config(self) -> None:
        """加载配置并验证"""
        try:
            self._config = {
                'APP_NAME': os.getenv('APP_NAME', 'MyApp'),
                'DEBUG': os.getenv('DEBUG', 'False'),
                'DATABASE_URL': os.getenv('DATABASE_URL', ''),
                'SECRET_KEY': os.getenv('SECRET_KEY', ''),
                'PORT': os.getenv('PORT', '8000'),
                'HOST': os.getenv('HOST', '0.0.0.0'),
                'LOG_LEVEL': os.getenv('LOG_LEVEL', 'INFO'),
            }
            self._validate_config()
        except Exception as e:
            raise RuntimeError(f"配置加载失败: {str(e)}")

    def _validate_config(self) -> None:
        """验证配置项"""
        errors = []

        # 验证必填配置
        if not self._config.get('SECRET_KEY'):
            errors.append("SECRET_KEY 环境变量未设置")

        if not self._config.get('DATABASE_URL'):
            errors.append("DATABASE_URL 环境变量未设置")

        # 验证 DEBUG 类型
        debug = self._config.get('DEBUG', '')
        if debug.lower() not in ['true', 'false', '1', '0', '']:
            errors.append(f"DEBUG 环境变量类型错误: {debug}")

        # 验证 PORT 类型和范围
        port = self._config.get('PORT', '8000')
        try:
            port_int = int(port)
            if port_int <= 0 or port_int > 65535:
                errors.append(f"PORT 环境变量值超出有效范围(1-65535): {port}")
        except ValueError:
            errors.append(f"PORT 环境变量类型错误，应为整数: {port}")

        # 验证 LOG_LEVEL
        valid_log_levels = ['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL']
        log_level = self._config.get('LOG_LEVEL', 'INFO').upper()
        if log_level not in valid_log_levels:
            errors.append(f"LOG_LEVEL 环境变量值无效: {log_level}，可选值: {valid_log_levels}")

        if errors:
            raise ValueError("配置验证失败: " + "; ".join(errors))

    def get(self, key: str, default: Any = None) -> Any:
        """获取配置值"""
        return self._config.get(key, default)

    def __getitem__(self, key: str) -> Any:
        """支持字典式访问"""
        return self._config[key]

    def __contains__(self, key: str) -> bool:
        """支持 in 操作符"""
        return key in self._config

    @property
    def debug(self) -> bool:
        """获取调试模式状态"""
        return self._config.get('DEBUG', 'False').lower() in ['true', '1']

    @property
    def port(self) -> int:
        """获取端口号"""
        return int(self._config.get('PORT', '8000'))

    @property
    def host(self) -> str:
        """获取主机地址"""
        return self._config.get('HOST', '0.0.0.0')

    @property
    def secret_key(self) -> str:
        """获取密钥"""
        return self._config.get('SECRET_KEY', '')

    @property
    def database_url(self) -> str:
        """获取数据库连接URL"""
        return self._config.get('DATABASE_URL', '')

    @property
    def log_level(self) -> str:
        """获取日志级别"""
        return self._config.get('LOG_LEVEL', 'INFO').upper()


# 创建全局配置实例
settings = Settings()
